const insertDerivedConsumableBuffs = `-- name: InsertDerivedConsumableBuffs :execrows
WITH RECURSIVE roots AS (
    SELECT
        c.dataset_id,
        c.item_id,
        root_spell_id
    FROM dbc_consumables c
    CROSS JOIN LATERAL unnest(c.item_spell_ids) AS root_spell_id
    WHERE c.dataset_id = $1
), spell_graph AS (
    SELECT
        r.dataset_id,
        r.item_id,
        r.root_spell_id,
        r.root_spell_id AS spell_id,
        ARRAY[r.root_spell_id]::int[] AS path
    FROM roots r

    UNION ALL

    SELECT
        graph.dataset_id,
        graph.item_id,
        graph.root_spell_id,
        triggered.effect_trigger_spell,
        graph.path || triggered.effect_trigger_spell
    FROM spell_graph graph
    JOIN dbc_spell_effects triggered
      ON triggered.dataset_id = graph.dataset_id
     AND triggered.spell_id = graph.spell_id
     AND triggered.difficulty_id = 0
    -- A learn-spell effect names the taught spell in this field; it does not
    -- execute that spell and must not create a consumable buff edge.
    WHERE triggered.effect <> 36
      AND triggered.effect_trigger_spell <> 0
      AND NOT triggered.effect_trigger_spell = ANY(graph.path)
      AND cardinality(graph.path) < 8
)
INSERT INTO dbc_consumable_buffs (dataset_id, item_id, spell_id, spell_name)
SELECT DISTINCT
    graph.dataset_id,
    graph.item_id,
    spell.spell_id,
    spell.name
FROM spell_graph graph
JOIN dbc_spells spell
  ON spell.dataset_id = graph.dataset_id
 AND spell.spell_id = graph.spell_id
WHERE EXISTS (
    SELECT 1
    FROM dbc_spell_effects effect
    WHERE effect.dataset_id = spell.dataset_id
      AND effect.spell_id = spell.spell_id
      AND effect.difficulty_id = 0
      AND effect.effect IN (6, 174)
)
`

func (q *sqlQuerier) InsertDerivedConsumableBuffs(ctx context.Context, datasetID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, insertDerivedConsumableBuffs, datasetID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const insertDerivedConsumables = `-- name: InsertDerivedConsumables :execrows
WITH eligible_item_spells AS (
    SELECT
        wit.dataset_id,
        wit.entry AS item_id,
        array_agg(slot.spell_id ORDER BY slot.slot) AS item_spell_ids
    FROM world_item_template wit
    CROSS JOIN LATERAL (VALUES
        (1, wit.spellid_1, wit.spelltrigger_1),
        (2, wit.spellid_2, wit.spelltrigger_2),
        (3, wit.spellid_3, wit.spelltrigger_3),
        (4, wit.spellid_4, wit.spelltrigger_4),
        (5, wit.spellid_5, wit.spelltrigger_5)
    ) AS slot(slot, spell_id, trigger)
    WHERE wit.dataset_id = $1
      AND slot.spell_id <> 0
      AND slot.trigger = 0
      -- Codices can list both a learn-spell wrapper and the taught class spell
      -- as on-use slots. Reject the whole item when any on-use slot teaches a
      -- spell, otherwise the taught aura remains as a false consumable effect.
      AND NOT EXISTS (
          SELECT 1
          FROM dbc_spell_effects learn_effect
          WHERE learn_effect.dataset_id = wit.dataset_id
            AND learn_effect.spell_id = ANY(ARRAY[
                CASE WHEN wit.spelltrigger_1 = 0 THEN wit.spellid_1 ELSE 0 END,
                CASE WHEN wit.spelltrigger_2 = 0 THEN wit.spellid_2 ELSE 0 END,
                CASE WHEN wit.spelltrigger_3 = 0 THEN wit.spellid_3 ELSE 0 END,
                CASE WHEN wit.spelltrigger_4 = 0 THEN wit.spellid_4 ELSE 0 END,
                CASE WHEN wit.spelltrigger_5 = 0 THEN wit.spellid_5 ELSE 0 END
            ])
            AND learn_effect.difficulty_id = 0
            AND learn_effect.effect = 36
      )
    GROUP BY wit.dataset_id, wit.entry
)
INSERT INTO dbc_consumables (
    dataset_id,
    item_id,
    item_name,
    item_quality,
    item_icon,
    item_spell_ids
)
SELECT
    wit.dataset_id,
    wit.entry,
    wit.name,
    wit.quality,
    COALESCE(NULLIF(wit.icon, ''), NULLIF(wdi.icon, ''), dbi.inventory_icon ->> 0, '')::text,
    eligible.item_spell_ids
FROM world_item_template wit
JOIN eligible_item_spells eligible
  ON eligible.dataset_id = wit.dataset_id
 AND eligible.item_id = wit.entry
LEFT JOIN world_display_info wdi
    ON wdi.dataset_id = wit.dataset_id AND wdi.id = wit.display_id
LEFT JOIN dbc_item_display_info dbi
    ON dbi.dataset_id = wit.dataset_id AND dbi.id = wit.display_id
WHERE wit.dataset_id = $1
  AND (
      wit.class = 0
      OR (
          wit.inventory_type = 0
          AND (
              (wit.spellid_1 <> 0 AND wit.spelltrigger_1 = 0) OR
              (wit.spellid_2 <> 0 AND wit.spelltrigger_2 = 0) OR
              (wit.spellid_3 <> 0 AND wit.spelltrigger_3 = 0) OR
              (wit.spellid_4 <> 0 AND wit.spelltrigger_4 = 0) OR
              (wit.spellid_5 <> 0 AND wit.spelltrigger_5 = 0)
          )
          AND (
              wit.stackable > 1
              OR (
                  -- Weapon oils are trade goods with multiple expendable charges,
                  -- rather than stackable items or direct aura spells.
                  wit.class = 7
                  AND (
                      (wit.spellid_1 <> 0 AND wit.spelltrigger_1 = 0 AND wit.spellcharges_1 < 0) OR
                      (wit.spellid_2 <> 0 AND wit.spelltrigger_2 = 0 AND wit.spellcharges_2 < 0) OR
                      (wit.spellid_3 <> 0 AND wit.spelltrigger_3 = 0 AND wit.spellcharges_3 < 0) OR
                      (wit.spellid_4 <> 0 AND wit.spelltrigger_4 = 0 AND wit.spellcharges_4 < 0) OR
                      (wit.spellid_5 <> 0 AND wit.spelltrigger_5 = 0 AND wit.spellcharges_5 < 0)
                  )
              )
              OR EXISTS (
                  SELECT 1
                  FROM dbc_spell_effects effect
                  WHERE effect.dataset_id = wit.dataset_id
                    AND effect.spell_id = ANY(eligible.item_spell_ids)
                    AND effect.difficulty_id = 0
                    AND effect.effect IN (6, 174)
              )
          )
      )
  )
  -- Mount items are reusable utility items, not consumables. Their use spell
  -- applies a mounted aura directly, which otherwise matches the generic aura
  -- fallback for non-stackable consumables.
  AND NOT EXISTS (
      SELECT 1
      FROM dbc_spell_effects mount_effect
      WHERE mount_effect.dataset_id = wit.dataset_id
        AND mount_effect.spell_id = ANY(eligible.item_spell_ids)
        AND mount_effect.difficulty_id = 0
        AND mount_effect.effect_aura = 78
  )
`

