const encountersByInstanceID = `-- name: EncountersByInstanceID :many
SELECT
  id, instance_id, name, remaining, boss, start_time, end_time, kill_type, map_id
FROM
  log_instance_encounters
WHERE
  instance_id = $1
`

func (q *sqlQuerier) EncountersByInstanceID(ctx context.Context, instanceID uuid.UUID) ([]LogInstanceEncounter, error) {
	rows, err := q.db.Query(ctx, encountersByInstanceID, instanceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []LogInstanceEncounter
	for rows.Next() {
		var i LogInstanceEncounter
		if err := rows.Scan(
			&i.ID,
			&i.InstanceID,
			&i.Name,
			&i.Remaining,
			&i.Boss,
			&i.StartTime,
			&i.EndTime,
			&i.KillType,
			&i.MapID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

