// Pages logical runs, then returns every upload in each selected duplicate group.
// The first row for each run is its representative: most boss encounters, then
// most total encounters, then the duplicate-group anchor and stable tie-breakers.
func (q *sqlQuerier) ListRecentInstanceGroups(ctx context.Context, arg ListRecentInstanceGroupsParams) ([]ListRecentInstanceGroupsRow, error) {
	rows, err := q.db.Query(ctx, listRecentInstanceGroups,
		arg.StartTime,
		arg.EndTime,
		arg.InstanceNames,
		arg.HasVideo,
		arg.RealmID,
		arg.GuildID,
		arg.PlayerGuid,
		arg.HasPositions,
		arg.PreferReplay,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRecentInstanceGroupsRow
	for rows.Next() {
		var i ListRecentInstanceGroupsRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Name,
			&i.RealmID,
			&i.RealmName,
			&i.UploaderID,
			&i.UploaderName,
			&i.UploadedAt,
			&i.FirstEncounterTime,
			&i.PlayerCount,
			&i.BossCount,
			&i.BossKills,
			&i.DurationMs,
			&i.CombatDurationMs,
			&i.GuildID,
			&i.GuildName,
			&i.HasYoutubeVideo,
			&i.DuplicateGroupID,
			&i.RecorderName,
			&i.DifficultyName,
			&i.MaxPlayers,
			&i.DynamicDifficulty,
			&i.HasPositions,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listRecentInstances = `-- name: ListRecentInstances :many
SELECT 
    li.id,
    li.hashed_slug as slug,
  COALESCE(NULLIF(btrim(li.name), ''), NULLIF(btrim(sm.instance_name), ''), li.name) as name,
    li.realm_id,
    wsr.name as realm_name,
    wlg.owner as uploader_id,
    u.username as uploader_name,
    wlg.created_at as uploaded_at,
    COALESCE(
        (SELECT MIN(lie.start_time) FROM log_instance_encounters lie WHERE lie.instance_id = li.id),
        wlg.created_at
    ) as first_encounter_time,
    (SELECT COUNT(*) FROM log_instance_players lip WHERE lip.instance_id = li.id) as player_count,
    (SELECT COUNT(*) FROM log_instance_encounters lie WHERE lie.instance_id = li.id AND lie.boss = true) as boss_count,
    (SELECT COUNT(*) FROM log_instance_encounters lie WHERE lie.instance_id = li.id AND lie.boss = true AND lie.kill_type IN ('clean', 'partial')) as boss_kills,
    COALESCE((SELECT EXTRACT(EPOCH FROM (MAX(lie.end_time) - MIN(lie.start_time))) * 1000 
     FROM log_instance_encounters lie WHERE lie.instance_id = li.id), 0)::float8 as duration_ms,
    iom.total_combat_duration_ms as combat_duration_ms,
    g.id as guild_id,
    g.name as guild_name,
    EXISTS (SELECT 1 FROM log_instance_youtube_timestamped yt WHERE yt.log_instance_id = li.id OR yt.instance_slug = li.hashed_slug) as has_youtube_video,
    li.duplicate_group_id,
    li.recorder_name,
    li.difficulty_name,
    li.max_players,
    li.dynamic_difficulty
FROM log_instances li
JOIN parsed_log_group plg ON plg.id = li.log_group_id
JOIN wow_log_groups wlg ON wlg.id = plg.id
  AND plg.parse_generation = wlg.parse_generation
  AND plg.finalized_at IS NOT NULL
  AND NOT wlg.unlisted
LEFT JOIN instance_overview_metrics iom ON iom.instance_id = li.id
LEFT JOIN server_upload_meta sm ON sm.log_group_id = li.log_group_id
JOIN users u ON u.id = wlg.owner
JOIN wow_server_realms wsr ON wsr.id = li.realm_id
LEFT JOIN guilds g ON g.id = li.guild_id
WHERE true
    -- Filter by instance names
    AND CASE
        WHEN cardinality($1 :: text[]) > 0 THEN
      COALESCE(NULLIF(btrim(li.name), ''), NULLIF(btrim(sm.instance_name), ''), li.name) = ANY($1 :: text[])
        ELSE true
    END
    -- Filter by video presence
    AND CASE
        WHEN $2 :: text = 'true' THEN
            EXISTS (SELECT 1 FROM log_instance_youtube_timestamped yt WHERE yt.log_instance_id = li.id OR yt.instance_slug = li.hashed_slug)
        WHEN $2 :: text = 'false' THEN
            NOT EXISTS (SELECT 1 FROM log_instance_youtube_timestamped yt WHERE yt.log_instance_id = li.id OR yt.instance_slug = li.hashed_slug)
        ELSE true
    END
    -- Filter by realm
    AND CASE
        WHEN $3 :: uuid != '00000000-0000-0000-0000-000000000000'::uuid THEN
            li.realm_id = $3
        ELSE true
    END
    -- Filter by guild
    AND CASE
        WHEN $4 :: uuid != '00000000-0000-0000-0000-000000000000'::uuid THEN
            li.guild_id = $4
        ELSE true
    END
    -- Cursor pagination (first_encounter_time, id) - pass '0001-01-01' to skip
    AND CASE
        WHEN $5 :: timestamptz != '0001-01-01'::timestamptz THEN
            (COALESCE((SELECT MIN(lie.start_time) FROM log_instance_encounters lie WHERE lie.instance_id = li.id), wlg.created_at) < $5 
             OR (COALESCE((SELECT MIN(lie.start_time) FROM log_instance_encounters lie WHERE lie.instance_id = li.id), wlg.created_at) = $5 AND li.id < $6 :: uuid))
        ELSE true
    END
ORDER BY first_encounter_time DESC, li.id DESC
LIMIT $7
`

