const pruneStaleRankingsInstanceSummaries = `-- name: PruneStaleRankingsInstanceSummaries :execrows
DELETE FROM rankings_instance_summaries ris
WHERE ris.tenant_id = $1
  AND NOT EXISTS (
    SELECT 1
    FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
    WHERE edr.instance_name = ris.instance_name
      AND edr.difficulty_name = ris.difficulty_name
      AND edr.max_players = ris.max_players
  )
`

// Removes summary cards whose instance/difficulty/player-count combination no
// longer has any ranking rows visible to the current tenant context.
func (q *sqlQuerier) PruneStaleRankingsInstanceSummaries(ctx context.Context, tenantID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, pruneStaleRankingsInstanceSummaries, tenantID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rankingsBoxPlotStats = `-- name: RankingsBoxPlotStats :many
WITH fallback_representative_instances AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        li.id,
        COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM log_instances li
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = li.realm_id
    -- Scope representative selection by tenant and instance before calculating
    -- boss coverage. Without these filters, an instance-specific box plot ranks
    -- duplicate uploads that will only be discarded later.
    WHERE li.invalidated_at IS NULL
      AND (cardinality($2 :: text[]) = 0
           OR li.name = ANY($2 :: text[]))
      AND NOT EXISTS (
          SELECT 1
          FROM ranking_runs rr
          JOIN log_instances representative
            ON representative.id = rr.representative_instance_id
           AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
           AND representative.invalidated_at IS NULL
          JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
          WHERE rr.run_id = COALESCE(li.duplicate_group_id, li.id)
      )
    ORDER BY COALESCE(li.duplicate_group_id, li.id),
        -- Prefer the upload with the broadest boss-ranking coverage. The group
        -- anchor is the first upload, but it may be truncated before the final boss.
        (SELECT COUNT(DISTINCT coverage.encounter_name)
         FROM encounter_dps_rankings coverage
         WHERE coverage.instance_id = li.id
           AND coverage.encounter_id IS NOT NULL) DESC,
        (li.id = li.duplicate_group_id) DESC NULLS LAST,
        li.start_time ASC,
        li.id ASC
),
representative_instances AS (
    SELECT rr.representative_instance_id AS id, rr.run_id
    FROM ranking_runs rr
    JOIN log_instances representative
      ON representative.id = rr.representative_instance_id
     AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
     AND representative.invalidated_at IS NULL
    JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = rr.realm_id
    WHERE (cardinality($2 :: text[]) = 0
           OR rr.instance_name = ANY($2 :: text[]))
    UNION ALL
    SELECT id, run_id FROM fallback_representative_instances
),
deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, ri.run_id)
        edr.player_guid,
        edr.encounter_name,
        edr.player_class,
        edr.player_spec,
        edr.player_sub_spec,
        edr.realm_id,
        edr.damage_done,
        edr.healing_done,
        edr.absorbed_done,
        edr.duration_secs,
        ri.run_id
    FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
    JOIN representative_instances ri ON ri.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    WHERE CASE
        WHEN cardinality($2 :: text[]) > 0 THEN edr.instance_name = ANY($2 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($3 :: text[]) > 0 THEN edr.encounter_name = ANY($3 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($4 :: text[]) > 0 THEN edr.realm_name = ANY($4 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $5 :: text != '' THEN edr.player_role = $5
        ELSE true
    END
    AND CASE
        WHEN $6 :: bigint > 0 THEN edr.killed_at >= now() - make_interval(days => $6::int)
        ELSE true
    END
    AND CASE
        WHEN cardinality($7 :: text[]) > 0 THEN edr.difficulty_name = ANY($7 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $8 :: smallint > 0 THEN edr.max_players = $8
        ELSE true
    END
    ORDER BY edr.player_guid, edr.encounter_name, ri.run_id,
        (CASE WHEN $9 :: text = 'hps' THEN edr.hps ELSE edr.dps END) DESC
),
realm_encounter_counts AS (
    SELECT
        d.realm_id,
        CASE
            WHEN cardinality($3 :: text[]) > 0
                THEN cardinality($3 :: text[])::bigint
            ELSE COUNT(DISTINCT d.encounter_name)
        END AS encounter_count
    FROM deduped d
    GROUP BY d.realm_id
),
per_run AS (
    SELECT
        d.player_class,
        d.player_spec,
        d.player_sub_spec,
        (CASE WHEN $9 :: text = 'hps'
            THEN SUM(d.healing_done + d.absorbed_done)::double precision / NULLIF(SUM(d.duration_secs), 0)
            ELSE SUM(d.damage_done)::double precision / NULLIF(SUM(d.duration_secs), 0)
        END)::double precision AS metric_value
    FROM deduped d
    JOIN realm_encounter_counts rec ON rec.realm_id = d.realm_id
    GROUP BY d.player_guid, d.run_id, d.player_class, d.player_spec, d.player_sub_spec, rec.encounter_count
    HAVING COUNT(DISTINCT d.encounter_name) = rec.encounter_count
)
SELECT
    s.player_class,
    s.player_spec,
    s.player_sub_spec,
    s.min_dps,
    s.q1_dps,
    s.median_dps,
    s.q3_dps,
    s.max_dps,
    s.count
FROM (
    SELECT
        d.player_class,
        (CASE WHEN $1 :: bool THEN '' ELSE d.player_spec END)::text AS player_spec,
        (CASE WHEN $1 :: bool THEN '' ELSE d.player_sub_spec END)::text AS player_sub_spec,
        PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY d.metric_value) AS q1_dps,
        PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY d.metric_value) AS median_dps,
        PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY d.metric_value) AS q3_dps,
        -- When we have enough samples, trim the bottom 5% to exclude
        -- outliers (e.g. early deaths). Otherwise show the true minimum.
        CASE WHEN COUNT(*) > 100
            THEN PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY d.metric_value)
            ELSE MIN(d.metric_value)
        END::double precision AS min_dps,
        MAX(d.metric_value)::double precision AS max_dps,
        COUNT(*)::bigint AS count
    FROM per_run d
    WHERE d.metric_value > 0
    GROUP BY d.player_class,
        (CASE WHEN $1 :: bool THEN '' ELSE d.player_spec END)::text,
        (CASE WHEN $1 :: bool THEN '' ELSE d.player_sub_spec END)::text
) s
ORDER BY s.median_dps DESC
`

type RankingsBoxPlotStatsParams struct {
	GroupByClass     bool     `db:"group_by_class" json:"group_by_class"`
	InstanceNames    []string `db:"instance_names" json:"instance_names"`
	EncounterNames   []string `db:"encounter_names" json:"encounter_names"`
	RealmNames       []string `db:"realm_names" json:"realm_names"`
	Role             string   `db:"role" json:"role"`
	SinceDays        int64    `db:"since_days" json:"since_days"`
	DifficultyNames  []string `db:"difficulty_names" json:"difficulty_names"`
	FilterMaxPlayers int16    `db:"filter_max_players" json:"filter_max_players"`
	Metric           string   `db:"metric" json:"metric"`
}

type RankingsBoxPlotStatsRow struct {
	PlayerClass   string  `db:"player_class" json:"player_class"`
	PlayerSpec    string  `db:"player_spec" json:"player_spec"`
	PlayerSubSpec string  `db:"player_sub_spec" json:"player_sub_spec"`
	MinDps        float64 `db:"min_dps" json:"min_dps"`
	Q1Dps         float64 `db:"q1_dps" json:"q1_dps"`
	MedianDps     float64 `db:"median_dps" json:"median_dps"`
	Q3Dps         float64 `db:"q3_dps" json:"q3_dps"`
	MaxDps        float64 `db:"max_dps" json:"max_dps"`
	Count         int64   `db:"count" json:"count"`
}

// Returns box plot statistics (min, q1, median, q3, max, count) per class/spec.
// DPS is aggregated per run (sum damage / sum duration across encounters in one
// instance run), so each run is one data point. Matches leaderboard aggregation.
// Explicit encounter selections define the required run coverage. Without an
// explicit selection, compute coverage per realm because different realms can
// record different encounter names for the same instance.
// Aggregate per player per run: sum damage/duration across encounters in one run.
// Each run becomes one data point for percentile computation.
// Only include runs where the player completed ALL encounters as the same spec.
func (q *sqlQuerier) RankingsBoxPlotStats(ctx context.Context, arg RankingsBoxPlotStatsParams) ([]RankingsBoxPlotStatsRow, error) {
	rows, err := q.db.Query(ctx, rankingsBoxPlotStats,
		arg.GroupByClass,
		arg.InstanceNames,
		arg.EncounterNames,
		arg.RealmNames,
		arg.Role,
		arg.SinceDays,
		arg.DifficultyNames,
		arg.FilterMaxPlayers,
		arg.Metric,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsBoxPlotStatsRow
	for rows.Next() {
		var i RankingsBoxPlotStatsRow
		if err := rows.Scan(
			&i.PlayerClass,
			&i.PlayerSpec,
			&i.PlayerSubSpec,
			&i.MinDps,
			&i.Q1Dps,
			&i.MedianDps,
			&i.Q3Dps,
			&i.MaxDps,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsClearTimeStats = `-- name: RankingsClearTimeStats :many
WITH deduped AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        COALESCE(sr.ranked_duration_ms, sr.duration_ms) / 1000.0 AS duration_secs
    FROM instance_speedruns sr
    JOIN log_instances li ON li.id = sr.instance_id
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms wsr ON wsr.id = sr.realm_id
    WHERE sr.instance_name = $1
      AND sr.qualified = true
      AND CASE
          WHEN $2 :: bigint > 0 THEN
              COALESCE(sr.ranked_completion_time, sr.completion_time) >= now() - make_interval(days => $2::int)
          ELSE true
      END
    ORDER BY COALESCE(li.duplicate_group_id, li.id), COALESCE(sr.ranked_duration_ms, sr.duration_ms)
)
SELECT
    PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY d.duration_secs)::double precision AS q1_secs,
    PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY d.duration_secs)::double precision AS median_secs,
    PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY d.duration_secs)::double precision AS q3_secs,
    MIN(d.duration_secs)::double precision AS min_secs,
    MAX(d.duration_secs)::double precision AS max_secs,
    COUNT(*)::bigint AS count
FROM deduped d
WHERE d.duration_secs > 0
HAVING COUNT(*) > 0
`

type RankingsClearTimeStatsParams struct {
	InstanceName string `db:"instance_name" json:"instance_name"`
	SinceDays    int64  `db:"since_days" json:"since_days"`
}

type RankingsClearTimeStatsRow struct {
	Q1Secs     float64 `db:"q1_secs" json:"q1_secs"`
	MedianSecs float64 `db:"median_secs" json:"median_secs"`
	Q3Secs     float64 `db:"q3_secs" json:"q3_secs"`
	MinSecs    float64 `db:"min_secs" json:"min_secs"`
	MaxSecs    float64 `db:"max_secs" json:"max_secs"`
	Count      int64   `db:"count" json:"count"`
}

// Box plot stats on qualified full-clear durations (seconds) for one
// instance, the clear-time counterpart of RankingsKillTimeStats. Uses ranked
// clear timing like the speedrun board and keeps the fastest run per
