const rankingsKillTimeLeaderboard = `-- name: RankingsKillTimeLeaderboard :many
WITH deduped AS (
    SELECT DISTINCT ON (lie.name, COALESCE(li.duplicate_group_id, li.id))
        lie.id AS encounter_id,
        lie.name AS encounter_name,
        li.id AS instance_id,
        li.hashed_slug AS log_hashed_slug,
        li.name AS instance_name,
        COALESCE(g.name, '')::text AS guild_name,
        wsr.name AS realm_name,
        EXTRACT(EPOCH FROM (lie.end_time - lie.start_time))::double precision AS duration_secs,
        lie.end_time AS killed_at
    FROM log_instance_encounters lie
    JOIN log_instances li ON li.id = lie.instance_id
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms wsr ON wsr.id = li.realm_id
    LEFT JOIN guilds g ON g.id = li.guild_id
    WHERE li.name = $3
      AND lie.boss = true
      AND lie.kill_type = 'clean'
      AND CASE
          WHEN $4 :: text != '' THEN lie.name = $4
          ELSE true
      END
      AND CASE
          WHEN $5 :: bigint > 0 THEN lie.end_time >= now() - make_interval(days => $5::int)
          ELSE true
      END
    ORDER BY lie.name, COALESCE(li.duplicate_group_id, li.id),
             EXTRACT(EPOCH FROM (lie.end_time - lie.start_time)) ASC
)
SELECT
    d.encounter_id,
    d.encounter_name,
    d.instance_id,
    d.log_hashed_slug,
    d.instance_name,
    d.guild_name,
    d.realm_name,
    d.duration_secs,
    d.killed_at,
    COUNT(*) OVER() AS total_count
FROM deduped d
WHERE d.duration_secs > 0
ORDER BY d.duration_secs ASC
LIMIT $2::bigint OFFSET $1::bigint
`

type RankingsKillTimeLeaderboardParams struct {
	QueryOffset   int64  `db:"query_offset" json:"query_offset"`
	QueryLimit    int64  `db:"query_limit" json:"query_limit"`
	InstanceName  string `db:"instance_name" json:"instance_name"`
	EncounterName string `db:"encounter_name" json:"encounter_name"`
	SinceDays     int64  `db:"since_days" json:"since_days"`
}

type RankingsKillTimeLeaderboardRow struct {
	EncounterID   uuid.UUID          `db:"encounter_id" json:"encounter_id"`
	EncounterName string             `db:"encounter_name" json:"encounter_name"`
	InstanceID    uuid.UUID          `db:"instance_id" json:"instance_id"`
	LogHashedSlug pgtype.Text        `db:"log_hashed_slug" json:"log_hashed_slug"`
	InstanceName  string             `db:"instance_name" json:"instance_name"`
	GuildName     string             `db:"guild_name" json:"guild_name"`
	RealmName     string             `db:"realm_name" json:"realm_name"`
	DurationSecs  float64            `db:"duration_secs" json:"duration_secs"`
	KilledAt      pgtype.Timestamptz `db:"killed_at" json:"killed_at"`
	TotalCount    int64              `db:"total_count" json:"total_count"`
}

// Paginated leaderboard of fastest encounter kills, ordered by duration.
// Deduplicates encounters across duplicate log groups (keeps fastest per group).
func (q *sqlQuerier) RankingsKillTimeLeaderboard(ctx context.Context, arg RankingsKillTimeLeaderboardParams) ([]RankingsKillTimeLeaderboardRow, error) {
	rows, err := q.db.Query(ctx, rankingsKillTimeLeaderboard,
		arg.QueryOffset,
		arg.QueryLimit,
		arg.InstanceName,
		arg.EncounterName,
		arg.SinceDays,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsKillTimeLeaderboardRow
	for rows.Next() {
		var i RankingsKillTimeLeaderboardRow
		if err := rows.Scan(
			&i.EncounterID,
			&i.EncounterName,
			&i.InstanceID,
			&i.LogHashedSlug,
			&i.InstanceName,
			&i.GuildName,
			&i.RealmName,
			&i.DurationSecs,
			&i.KilledAt,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsKillTimeStats = `-- name: RankingsKillTimeStats :many
WITH deduped AS (
    SELECT DISTINCT ON (lie.name, COALESCE(li.duplicate_group_id, li.id))
        lie.name AS encounter_name,
        EXTRACT(EPOCH FROM (lie.end_time - lie.start_time))::double precision AS duration_secs
    FROM log_instance_encounters lie
    JOIN log_instances li ON li.id = lie.instance_id
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms wsr ON wsr.id = li.realm_id
    WHERE li.name = $1
      AND lie.boss = true
      AND lie.kill_type = 'clean'
      AND CASE
          WHEN $2 :: bigint > 0 THEN lie.end_time >= now() - make_interval(days => $2::int)
          ELSE true
      END
    ORDER BY lie.name, COALESCE(li.duplicate_group_id, li.id), lie.end_time DESC
)
SELECT
    s.encounter_name,
    s.min_secs,
    s.q1_secs,
    s.median_secs,
    s.q3_secs,
    s.max_secs,
    s.count
FROM (
    SELECT
        d.encounter_name,
        PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY d.duration_secs) AS q1_secs,
        PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY d.duration_secs) AS median_secs,
        PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY d.duration_secs) AS q3_secs,
        MIN(d.duration_secs)::double precision AS min_secs,
        MAX(d.duration_secs)::double precision AS max_secs,
        COUNT(*)::bigint AS count
    FROM deduped d
    WHERE d.duration_secs > 0
    GROUP BY d.encounter_name
) s
ORDER BY (s.encounter_name = 'Trash'), s.encounter_name
`

type RankingsKillTimeStatsParams struct {
	InstanceName string `db:"instance_name" json:"instance_name"`
	SinceDays    int64  `db:"since_days" json:"since_days"`
}

type RankingsKillTimeStatsRow struct {
	EncounterName string  `db:"encounter_name" json:"encounter_name"`
	MinSecs       float64 `db:"min_secs" json:"min_secs"`
	Q1Secs        float64 `db:"q1_secs" json:"q1_secs"`
	MedianSecs    float64 `db:"median_secs" json:"median_secs"`
	Q3Secs        float64 `db:"q3_secs" json:"q3_secs"`
	MaxSecs       float64 `db:"max_secs" json:"max_secs"`
	Count         int64   `db:"count" json:"count"`
}

// Box plot stats on encounter duration (seconds) per encounter name.
// Deduplicates encounters across duplicate log groups.
func (q *sqlQuerier) RankingsKillTimeStats(ctx context.Context, arg RankingsKillTimeStatsParams) ([]RankingsKillTimeStatsRow, error) {
	rows, err := q.db.Query(ctx, rankingsKillTimeStats, arg.InstanceName, arg.SinceDays)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsKillTimeStatsRow
	for rows.Next() {
		var i RankingsKillTimeStatsRow
		if err := rows.Scan(
			&i.EncounterName,
			&i.MinSecs,
			&i.Q1Secs,
			&i.MedianSecs,
			&i.Q3Secs,
			&i.MaxSecs,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsLeaderboard = `-- name: RankingsLeaderboard :many
WITH candidate_runs AS (
    -- Class/spec/sub-spec/role filters usually narrow the leaderboard to a small
    -- fraction of raid logs. Find those duplicate groups first so representative
    -- selection does not calculate boss coverage for every matching instance ever uploaded.
    SELECT DISTINCT COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM encounter_dps_rankings candidate
    JOIN log_instances li ON li.id = candidate.instance_id
    JOIN wow_log_groups candidate_group ON candidate_group.id = li.log_group_id AND NOT candidate_group.unlisted
    WHERE ($4 :: text != '' OR $5 :: text != '' OR $6 :: text != '' OR $7 :: text != '')
      AND (cardinality($8 :: text[]) = 0
           OR candidate.instance_name = ANY($8 :: text[]))
      AND ($4 :: text = '' OR candidate.player_class = $4)
      AND ($5 :: text = '' OR candidate.player_spec = $5)
      AND ($6 :: text = '' OR candidate.player_sub_spec = $6)
      AND ($7 :: text = '' OR candidate.player_role = $7)
),
fallback_representative_instances AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        li.id,
        COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM log_instances li
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = li.realm_id
    -- Apply tenant RLS before calculating boss coverage, then avoid unrelated
    -- instances and duplicate groups that cannot contribute.
    -- When a player archetype is selected, candidate_runs narrows further.
    WHERE li.invalidated_at IS NULL
      AND (cardinality($8 :: text[]) = 0
           OR li.name = ANY($8 :: text[]))
      AND (($4 :: text = '' AND $5 :: text = '' AND $6 :: text = '' AND $7 :: text = '')
           OR COALESCE(li.duplicate_group_id, li.id) IN (SELECT run_id FROM candidate_runs))
      AND NOT EXISTS (
          SELECT 1
          FROM ranking_runs rr
          JOIN log_instances representative ON representative.id = rr.representative_instance_id
           AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
         AND representative.invalidated_at IS NULL

          JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
          WHERE rr.run_id = COALESCE(li.duplicate_group_id, li.id)
      )
    ORDER BY COALESCE(li.duplicate_group_id, li.id),
        -- Prefer the upload with the broadest boss-ranking coverage. The group
        -- anchor is the first upload, but it may be truncated before the final boss.
        (SELECT COUNT(DISTINCT coverage.encounter_name)
         FROM encounter_dps_rankings coverage
         WHERE coverage.instance_id = li.id
           AND coverage.encounter_id IS NOT NULL) DESC,
        (li.id = li.duplicate_group_id) DESC NULLS LAST,
        li.start_time ASC,
        li.id ASC
),
representative_instances AS (
    SELECT rr.representative_instance_id AS id, rr.run_id
    FROM ranking_runs rr
    JOIN log_instances representative ON representative.id = rr.representative_instance_id
     AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
     AND representative.invalidated_at IS NULL

    JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = rr.realm_id
    WHERE (cardinality($8 :: text[]) = 0
           OR rr.instance_name = ANY($8 :: text[]))
      AND (($4 :: text = '' AND $5 :: text = '' AND $6 :: text = '' AND $7 :: text = '')
           OR rr.run_id IN (SELECT run_id FROM candidate_runs))
    UNION ALL
    SELECT id, run_id FROM fallback_representative_instances
),
deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, ri.run_id)
        edr.player_guid,
        edr.player_name,
        edr.player_class,
        edr.player_spec,
        edr.player_sub_spec,
        edr.player_role,
        edr.player_level,
        edr.instance_name,
        edr.encounter_name,
        edr.difficulty_name,
        edr.max_players,
        edr.realm_id,
        edr.realm_name,
        edr.guild_name,
        edr.damage_done,
        edr.healing_done,
        edr.absorbed_done,
        edr.alive_percentage,
        edr.player_deaths,
        edr.duration_secs,
        edr.avg_ilvl,
        COALESCE(NULLIF(edr_instance.hashed_slug, ''), edr.instance_id::text) AS log_hashed_slug,
        edr.killed_at,
        tb.sub_spec AS talent_sub_spec,
        tb.talent_layout AS talent_layout,
        ri.run_id
    FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
    JOIN representative_instances ri ON ri.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    LEFT JOIN talent_builds tb ON tb.id = edr.talent_build_id
    WHERE CASE
        WHEN cardinality($8 :: text[]) > 0 THEN edr.instance_name = ANY($8 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($9 :: text[]) > 0 THEN edr.encounter_name = ANY($9 :: text[])
        ELSE true
    END
    AND CASE
        WHEN cardinality($10 :: text[]) > 0 THEN edr.realm_name = ANY($10 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $4 :: text != '' THEN edr.player_class = $4
        ELSE true
    END
    AND CASE
        WHEN $5 :: text != '' THEN edr.player_spec = $5
        ELSE true
    END
    AND CASE
        WHEN $6 :: text != '' THEN edr.player_sub_spec = $6
        ELSE true
    END
    AND CASE
        WHEN $7 :: text != '' THEN edr.player_role = $7
        ELSE true
    END
    AND CASE
        WHEN $11 :: bigint > 0 THEN edr.killed_at >= now() - make_interval(days => $11::int)
        ELSE true
    END
    AND CASE
        WHEN $12 :: bool THEN edr.player_class != 'Unknown' AND edr.player_spec != 'Unknown'
        ELSE true
    END
    AND CASE
        WHEN cardinality($13 :: text[]) > 0 THEN edr.difficulty_name = ANY($13 :: text[])
        ELSE true
    END
    AND CASE
        WHEN $14 :: smallint > 0 THEN edr.max_players = $14
        ELSE true
    END
    AND (CASE WHEN $1 :: text = 'hps' THEN edr.hps ELSE edr.dps END) > 0
    ORDER BY edr.player_guid, edr.encounter_name, ri.run_id,
        (CASE WHEN $1 :: text = 'hps' THEN edr.hps ELSE edr.dps END) DESC
),
realm_encounter_counts AS (
    SELECT
        d.realm_id,
        CASE
            WHEN cardinality($9 :: text[]) > 0
                THEN cardinality($9 :: text[])::bigint
            ELSE COUNT(DISTINCT d.encounter_name)
        END AS encounter_count
    FROM deduped d
    GROUP BY d.realm_id
),
per_run AS (
    SELECT
        d.player_guid,
        d.run_id,
        ((array_agg(d.player_name ORDER BY d.damage_done DESC))[1])::text AS player_name,
        ((array_agg(d.player_class ORDER BY d.damage_done DESC))[1])::text AS player_class,
        (string_agg(DISTINCT d.player_spec, '/' ORDER BY d.player_spec))::text AS player_spec,
        (string_agg(DISTINCT d.player_sub_spec, '/' ORDER BY d.player_sub_spec))::text AS player_sub_spec,
        ((array_agg(d.player_role ORDER BY d.damage_done DESC))[1])::text AS player_role,
        MAX(d.player_level)::smallint AS player_level,
        ((array_agg(d.instance_name ORDER BY d.damage_done DESC))[1])::text AS instance_name,
        ((array_agg(d.encounter_name ORDER BY d.damage_done DESC))[1])::text AS encounter_name,
        ((array_agg(d.difficulty_name ORDER BY d.damage_done DESC))[1])::text AS difficulty_name,
        MAX(d.max_players)::smallint AS max_players,
        ((array_agg(d.realm_id ORDER BY d.damage_done DESC))[1])::uuid AS realm_id,
        ((array_agg(d.realm_name ORDER BY d.damage_done DESC))[1])::text AS realm_name,
        ((array_agg(d.guild_name ORDER BY d.damage_done DESC))[1])::text AS guild_name,
        SUM(d.damage_done)::bigint AS damage_done,
        SUM(d.healing_done)::bigint AS healing_done,
        SUM(d.absorbed_done)::bigint AS absorbed_done,
        COALESCE((CASE
            WHEN COUNT(d.alive_percentage) = COUNT(*) THEN
                SUM(d.duration_secs * d.alive_percentage) / NULLIF(SUM(d.duration_secs), 0)
            ELSE NULL
        END), -1)::double precision AS alive_percentage,
        COALESCE((CASE
            WHEN COUNT(d.player_deaths) = COUNT(*) THEN SUM(d.player_deaths)
            ELSE NULL
        END), -1)::integer AS player_deaths,
        SUM(d.duration_secs)::double precision AS duration_secs,
        (SUM(d.damage_done)::double precision / NULLIF(SUM(d.duration_secs), 0))::double precision AS dps,
        (SUM(d.healing_done + d.absorbed_done)::double precision / NULLIF(SUM(d.duration_secs), 0))::double precision AS hps,
        COALESCE(MAX(d.avg_ilvl), 0)::smallint AS avg_ilvl,
        ((array_agg(d.log_hashed_slug ORDER BY d.damage_done DESC))[1])::text AS log_hashed_slug,
        MAX(d.killed_at)::timestamptz AS killed_at,
        COALESCE((array_agg(d.talent_sub_spec ORDER BY d.damage_done DESC))[1], '')::text AS talent_sub_spec,
        COALESCE((array_agg(d.talent_layout ORDER BY d.damage_done DESC))[1], '')::text AS talent_layout
    FROM deduped d
    JOIN realm_encounter_counts rec ON rec.realm_id = d.realm_id
    GROUP BY d.player_guid, d.run_id, rec.encounter_count
    -- Only include runs where player has data for ALL encounters on their realm.
    HAVING COUNT(DISTINCT d.encounter_name) = rec.encounter_count
),
aggregated AS (
    SELECT DISTINCT ON (pr.player_guid)
        pr.player_guid,
        pr.player_name,
        pr.player_class,
        pr.player_spec,
        pr.player_sub_spec,
        pr.player_role,
        pr.player_level,
        pr.instance_name,
        pr.encounter_name,
        pr.difficulty_name,
        pr.max_players,
        pr.realm_id,
        pr.realm_name,
        pr.guild_name,
        pr.damage_done,
        pr.healing_done,
        pr.absorbed_done,
        pr.alive_percentage,
        pr.player_deaths,
        pr.duration_secs,
        pr.dps,
        pr.hps,
        pr.avg_ilvl,
        pr.log_hashed_slug,
        pr.killed_at,
        pr.talent_sub_spec,
        pr.talent_layout
    FROM per_run pr
    ORDER BY pr.player_guid, (CASE WHEN $1 :: text = 'hps' THEN pr.hps ELSE pr.dps END) DESC
)
SELECT
    a.player_guid, a.player_name, a.player_class, a.player_spec, a.player_sub_spec, a.player_role, a.player_level, a.instance_name, a.encounter_name, a.difficulty_name, a.max_players, a.realm_id, a.realm_name, a.guild_name, a.damage_done, a.healing_done, a.absorbed_done, a.alive_percentage, a.player_deaths, a.duration_secs, a.dps, a.hps, a.avg_ilvl, a.log_hashed_slug, a.killed_at, a.talent_sub_spec, a.talent_layout,
    COUNT(*) OVER() AS total_count
FROM aggregated a
WHERE (CASE WHEN $1 :: text = 'hps' THEN a.hps ELSE a.dps END) > 0
ORDER BY (CASE WHEN $1 :: text = 'hps' THEN a.hps ELSE a.dps END) DESC
LIMIT $3::bigint
OFFSET $2::bigint
`

type RankingsLeaderboardParams struct {
	Metric           string   `db:"metric" json:"metric"`
	QueryOffset      int64    `db:"query_offset" json:"query_offset"`
	QueryLimit       int64    `db:"query_limit" json:"query_limit"`
	Class            string   `db:"class" json:"class"`
	Spec             string   `db:"spec" json:"spec"`
	SubSpec          string   `db:"sub_spec" json:"sub_spec"`
	Role             string   `db:"role" json:"role"`
	InstanceNames    []string `db:"instance_names" json:"instance_names"`
	EncounterNames   []string `db:"encounter_names" json:"encounter_names"`
	RealmNames       []string `db:"realm_names" json:"realm_names"`
	SinceDays        int64    `db:"since_days" json:"since_days"`
	HideUnknowns     bool     `db:"hide_unknowns" json:"hide_unknowns"`
	DifficultyNames  []string `db:"difficulty_names" json:"difficulty_names"`
	FilterMaxPlayers int16    `db:"filter_max_players" json:"filter_max_players"`
}

type RankingsLeaderboardRow struct {
	PlayerGuid      string             `db:"player_guid" json:"player_guid"`
	PlayerName      string             `db:"player_name" json:"player_name"`
	PlayerClass     string             `db:"player_class" json:"player_class"`
	PlayerSpec      string             `db:"player_spec" json:"player_spec"`
	PlayerSubSpec   string             `db:"player_sub_spec" json:"player_sub_spec"`
	PlayerRole      string             `db:"player_role" json:"player_role"`
	PlayerLevel     int16              `db:"player_level" json:"player_level"`
	InstanceName    string             `db:"instance_name" json:"instance_name"`
	EncounterName   string             `db:"encounter_name" json:"encounter_name"`
	DifficultyName  string             `db:"difficulty_name" json:"difficulty_name"`
	MaxPlayers      int16              `db:"max_players" json:"max_players"`
	RealmID         uuid.UUID          `db:"realm_id" json:"realm_id"`
	RealmName       string             `db:"realm_name" json:"realm_name"`
	GuildName       string             `db:"guild_name" json:"guild_name"`
	DamageDone      int64              `db:"damage_done" json:"damage_done"`
	HealingDone     int64              `db:"healing_done" json:"healing_done"`
	AbsorbedDone    int64              `db:"absorbed_done" json:"absorbed_done"`
	AlivePercentage float64            `db:"alive_percentage" json:"alive_percentage"`
	PlayerDeaths    int32              `db:"player_deaths" json:"player_deaths"`
	DurationSecs    float64            `db:"duration_secs" json:"duration_secs"`
	Dps             float64            `db:"dps" json:"dps"`
	Hps             float64            `db:"hps" json:"hps"`
	AvgIlvl         int16              `db:"avg_ilvl" json:"avg_ilvl"`
	LogHashedSlug   string             `db:"log_hashed_slug" json:"log_hashed_slug"`
	KilledAt        pgtype.Timestamptz `db:"killed_at" json:"killed_at"`
	TalentSubSpec   string             `db:"talent_sub_spec" json:"talent_sub_spec"`
	TalentLayout    string             `db:"talent_layout" json:"talent_layout"`
	TotalCount      int64              `db:"total_count" json:"total_count"`
}

// Returns paginated DPS rankings showing each player's best single run.
// A "run" is one instance_id (deduplicated by duplicate_group_id).
// Within a run, damage and duration are summed across encounters to get run DPS.
// Each player appears once with their highest-DPS run.
// Deduplicates by (player, encounter, duplicate_group) before aggregating.
// Explicit encounter selections define the required run coverage. Without an
// explicit selection, compute coverage per realm because different realms can
// record different encounter names for the same instance.
// Step 1: aggregate per player per run (sum encounters within a single instance run).
// Step 2: pick each player's best run.
func (q *sqlQuerier) RankingsLeaderboard(ctx context.Context, arg RankingsLeaderboardParams) ([]RankingsLeaderboardRow, error) {
	rows, err := q.db.Query(ctx, rankingsLeaderboard,
		arg.Metric,
		arg.QueryOffset,
		arg.QueryLimit,
		arg.Class,
		arg.Spec,
		arg.SubSpec,
		arg.Role,
		arg.InstanceNames,
		arg.EncounterNames,
		arg.RealmNames,
		arg.SinceDays,
		arg.HideUnknowns,
		arg.DifficultyNames,
		arg.FilterMaxPlayers,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsLeaderboardRow
	for rows.Next() {
		var i RankingsLeaderboardRow
		if err := rows.Scan(
			&i.PlayerGuid,
			&i.PlayerName,
			&i.PlayerClass,
			&i.PlayerSpec,
			&i.PlayerSubSpec,
			&i.PlayerRole,
			&i.PlayerLevel,
			&i.InstanceName,
			&i.EncounterName,
			&i.DifficultyName,
			&i.MaxPlayers,
			&i.RealmID,
			&i.RealmName,
			&i.GuildName,
			&i.DamageDone,
			&i.HealingDone,
			&i.AbsorbedDone,
			&i.AlivePercentage,
			&i.PlayerDeaths,
			&i.DurationSecs,
			&i.Dps,
			&i.Hps,
			&i.AvgIlvl,
			&i.LogHashedSlug,
			&i.KilledAt,
			&i.TalentSubSpec,
			&i.TalentLayout,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsRealmNames = `-- name: RankingsRealmNames :many
SELECT DISTINCT edr.realm_name
FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
WHERE edr.realm_name <> ''
ORDER BY edr.realm_name
`

// Distinct realm names that have DPS ranking data, for the realm filter dropdown.
// Rows with an empty realm name are excluded: they cannot be filtered on, and
// selecting "all realms" must collapse to no filter so those rows still appear.
func (q *sqlQuerier) RankingsRealmNames(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, rankingsRealmNames)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var realm_name string
		if err := rows.Scan(&realm_name); err != nil {
			return nil, err
		}
		items = append(items, realm_name)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsRowCount = `-- name: RankingsRowCount :one
SELECT COUNT(*)::bigint AS row_count
FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
`

// Total row count in encounter_dps_rankings (scoped by tenant RLS).
// Used as a staleness guard — if count hasn't changed, skip refresh.
func (q *sqlQuerier) RankingsRowCount(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, rankingsRowCount)
	var row_count int64
	err := row.Scan(&row_count)
	return row_count, err
}

const rankingsSuccessRates = `-- name: RankingsSuccessRates :many
WITH deduped AS (
    SELECT DISTINCT ON (lie.name, lie.kill_type, COALESCE(li.duplicate_group_id, li.id))
        lie.name AS encounter_name,
        lie.kill_type,
        lie.boss
    FROM log_instance_encounters lie
    JOIN log_instances li ON li.id = lie.instance_id
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms wsr ON wsr.id = li.realm_id
    WHERE li.name = $1
      AND lie.boss = true
      AND CASE
          WHEN cardinality($2 :: text[]) > 0 THEN li.difficulty_name = ANY($2 :: text[])
          ELSE true
      END
      AND CASE
          WHEN $3 :: smallint > 0 THEN li.max_players = $3
          ELSE true
      END
      AND CASE
          WHEN $4 :: bigint > 0 THEN lie.end_time >= now() - make_interval(days => $4::int)
          ELSE true
      END
    ORDER BY lie.name, lie.kill_type, COALESCE(li.duplicate_group_id, li.id), lie.end_time DESC
)
SELECT
    d.encounter_name,
    COUNT(*) FILTER (WHERE d.kill_type IN ('clean', 'partial'))::bigint AS kills,
    COUNT(*) FILTER (WHERE d.kill_type IN ('wipe', 'reset'))::bigint AS wipes,
    COUNT(*)::bigint AS total
FROM deduped d
GROUP BY d.encounter_name
ORDER BY (d.encounter_name = 'Trash'), d.encounter_name
`

type RankingsSuccessRatesParams struct {
	InstanceName     string   `db:"instance_name" json:"instance_name"`
	DifficultyNames  []string `db:"difficulty_names" json:"difficulty_names"`
	FilterMaxPlayers int16    `db:"filter_max_players" json:"filter_max_players"`
	SinceDays        int64    `db:"since_days" json:"since_days"`
}

type RankingsSuccessRatesRow struct {
	EncounterName string `db:"encounter_name" json:"encounter_name"`
	Kills         int64  `db:"kills" json:"kills"`
	Wipes         int64  `db:"wipes" json:"wipes"`
	Total         int64  `db:"total" json:"total"`
}

// Kill/wipe/total counts per encounter name within an instance.
// Deduplicates across duplicate log groups.
func (q *sqlQuerier) RankingsSuccessRates(ctx context.Context, arg RankingsSuccessRatesParams) ([]RankingsSuccessRatesRow, error) {
	rows, err := q.db.Query(ctx, rankingsSuccessRates,
		arg.InstanceName,
		arg.DifficultyNames,
		arg.FilterMaxPlayers,
		arg.SinceDays,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RankingsSuccessRatesRow
	for rows.Next() {
		var i RankingsSuccessRatesRow
		if err := rows.Scan(
			&i.EncounterName,
			&i.Kills,
			&i.Wipes,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rankingsSummaryLastRowCount = `-- name: RankingsSummaryLastRowCount :one
SELECT
    COALESCE(MAX(last_row_count), 0)::bigint AS last_row_count,
    COALESCE(MIN(query_version), 0)::smallint AS query_version
FROM rankings_instance_summaries
WHERE tenant_id = $1
`

type RankingsSummaryLastRowCountRow struct {
	LastRowCount int64 `db:"last_row_count" json:"last_row_count"`
	QueryVersion int16 `db:"query_version" json:"query_version"`
}

// Returns the last_row_count and minimum query_version stored in the
// summary table for a tenant. If no summaries exist yet, returns 0
// for both (forcing a refresh).
func (q *sqlQuerier) RankingsSummaryLastRowCount(ctx context.Context, tenantID uuid.UUID) (RankingsSummaryLastRowCountRow, error) {
	row := q.db.QueryRow(ctx, rankingsSummaryLastRowCount, tenantID)
	var i RankingsSummaryLastRowCountRow
	err := row.Scan(&i.LastRowCount, &i.QueryVersion)
	return i, err
}

const rankingsSummaryMaxUpdatedAt = `-- name: RankingsSummaryMaxUpdatedAt :one
SELECT COALESCE(MAX(updated_at), '1970-01-01'::timestamptz)::timestamptz AS max_updated_at
FROM rankings_instance_summaries
WHERE tenant_id = $1
`

// Most recent updated_at among summaries for a given tenant.
// Used by the dispatch worker to skip if refreshed recently.
func (q *sqlQuerier) RankingsSummaryMaxUpdatedAt(ctx context.Context, tenantID uuid.UUID) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, rankingsSummaryMaxUpdatedAt, tenantID)
	var max_updated_at pgtype.Timestamptz
	err := row.Scan(&max_updated_at)
	return max_updated_at, err
}

const rankingsSummaryStatus = `-- name: RankingsSummaryStatus :one
SELECT
    COUNT(*)::bigint AS summary_count,
    COALESCE(MIN(last_row_count), 0)::bigint AS min_last_row_count,
    COALESCE(MAX(last_row_count), 0)::bigint AS max_last_row_count,
    COALESCE(MIN(query_version), 0)::smallint AS query_version,
    MAX(updated_at)::timestamptz AS last_rebuilt_at
FROM rankings_instance_summaries
WHERE tenant_id = $1
`

type RankingsSummaryStatusRow struct {
	SummaryCount    int64              `db:"summary_count" json:"summary_count"`
	MinLastRowCount int64              `db:"min_last_row_count" json:"min_last_row_count"`
	MaxLastRowCount int64              `db:"max_last_row_count" json:"max_last_row_count"`
	QueryVersion    int16              `db:"query_version" json:"query_version"`
	LastRebuiltAt   pgtype.Timestamptz `db:"last_rebuilt_at" json:"last_rebuilt_at"`
}

// Returns aggregate refresh metadata for one tenant's precomputed summaries.
func (q *sqlQuerier) RankingsSummaryStatus(ctx context.Context, tenantID uuid.UUID) (RankingsSummaryStatusRow, error) {
	row := q.db.QueryRow(ctx, rankingsSummaryStatus, tenantID)
	var i RankingsSummaryStatusRow
	err := row.Scan(
		&i.SummaryCount,
		&i.MinLastRowCount,
		&i.MaxLastRowCount,
		&i.QueryVersion,
		&i.LastRebuiltAt,
	)
	return i, err
}

const upsertRankingsInstanceSummary = `-- name: UpsertRankingsInstanceSummary :exec
WITH fallback_representative_instances AS (
    SELECT DISTINCT ON (COALESCE(li.duplicate_group_id, li.id))
        li.id,
        COALESCE(li.duplicate_group_id, li.id) AS run_id
    FROM log_instances li
JOIN wow_log_groups li_group ON li_group.id = li.log_group_id AND NOT li_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = li.realm_id
    WHERE li.invalidated_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM ranking_runs rr
        JOIN log_instances representative ON representative.id = rr.representative_instance_id
         AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
         AND representative.invalidated_at IS NULL

        JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
        WHERE rr.run_id = COALESCE(li.duplicate_group_id, li.id)
    )
    ORDER BY COALESCE(li.duplicate_group_id, li.id),
        (SELECT COUNT(DISTINCT coverage.encounter_name)
         FROM encounter_dps_rankings coverage
         WHERE coverage.instance_id = li.id
           AND coverage.encounter_id IS NOT NULL) DESC,
        (li.id = li.duplicate_group_id) DESC NULLS LAST,
        li.start_time ASC,
        li.id ASC
),
representative_instances AS (
    SELECT rr.representative_instance_id AS id, rr.run_id
    FROM ranking_runs rr
    JOIN log_instances representative ON representative.id = rr.representative_instance_id
     AND COALESCE(representative.duplicate_group_id, representative.id) = rr.run_id
     AND representative.invalidated_at IS NULL

    JOIN wow_log_groups representative_group ON representative_group.id = representative.log_group_id AND NOT representative_group.unlisted
    JOIN wow_server_realms tenant_realm ON tenant_realm.id = rr.realm_id
    WHERE rr.instance_name = $1
      AND rr.difficulty_name = $2
      AND rr.max_players = $3
    UNION ALL
    SELECT id, run_id FROM fallback_representative_instances
),
deduped AS (
    SELECT DISTINCT ON (edr.player_guid, edr.encounter_name, ri.run_id)
        edr.player_guid, edr.player_name, edr.realm_name,
        edr.player_class, edr.encounter_name,
        edr.damage_done, edr.duration_secs, edr.dps,
        ri.run_id
    FROM encounter_dps_rankings edr
JOIN log_instances edr_instance ON edr_instance.id = edr.instance_id
JOIN wow_log_groups edr_group ON edr_group.id = edr_instance.log_group_id AND NOT edr_group.unlisted
    JOIN representative_instances ri ON ri.id = edr.instance_id
    JOIN wow_server_realms wsr ON wsr.id = edr.realm_id
    WHERE edr.instance_name = $1
      AND edr.difficulty_name = $2
      AND edr.max_players = $3
      AND edr.dps > 0
      -- Boss encounters only: trash is excluded from the top-3 preview by default.
      AND edr.encounter_name <> 'Trash'
    ORDER BY edr.player_guid, edr.encounter_name, ri.run_id, edr.dps DESC
),
instance_encounter_count AS (
    SELECT COUNT(DISTINCT d.encounter_name) AS cnt FROM deduped d
),
per_run AS (
    SELECT
        d.player_guid,
        d.run_id,
        (array_agg(d.player_name ORDER BY d.damage_done DESC))[1] AS player_name,
        (array_agg(d.realm_name ORDER BY d.damage_done DESC))[1] AS realm_name,
        (array_agg(d.player_class ORDER BY d.damage_done DESC))[1] AS player_class,
        (SUM(d.damage_done)::double precision / NULLIF(SUM(d.duration_secs), 0)) AS dps
    FROM deduped d
    GROUP BY d.player_guid, d.run_id
    HAVING COUNT(DISTINCT d.encounter_name) = (SELECT cnt FROM instance_encounter_count)
),
per_player AS (
    SELECT DISTINCT ON (pr.player_guid)
        pr.player_guid,
        pr.player_name,
        pr.realm_name,
        pr.player_class,
        pr.dps
    FROM per_run pr
    ORDER BY pr.player_guid, pr.dps DESC
),
stats AS (
    SELECT COUNT(DISTINCT player_guid)::bigint AS total_kills FROM deduped
),
top3 AS (
    SELECT player_name, realm_name, player_class, dps
    FROM per_player WHERE dps > 0
    ORDER BY dps DESC LIMIT 3
)
INSERT INTO rankings_instance_summaries (instance_name, difficulty_name, max_players, tenant_id, total_kills, top_players, last_row_count, query_version, updated_at)
VALUES (
    $1,
    $2,
    $3,
    $4,
    (SELECT total_kills FROM stats),
    COALESCE((SELECT json_agg(json_build_object(
        'player_name', t.player_name,
        'realm_name', t.realm_name,
        'player_class', t.player_class,
        'dps', t.dps
    )) FROM top3 t), '[]'::json),
    $5,
    $6,
    now()
)
ON CONFLICT (instance_name, difficulty_name, max_players, tenant_id) DO UPDATE SET
    total_kills = EXCLUDED.total_kills,
    top_players = EXCLUDED.top_players,
    last_row_count = EXCLUDED.last_row_count,
    query_version = EXCLUDED.query_version,
    updated_at = EXCLUDED.updated_at
`

type UpsertRankingsInstanceSummaryParams struct {
	InstanceName   string    `db:"instance_name" json:"instance_name"`
	DifficultyName string    `db:"difficulty_name" json:"difficulty_name"`
	MaxPlayers     int16     `db:"max_players" json:"max_players"`
	TenantID       uuid.UUID `db:"tenant_id" json:"tenant_id"`
	LastRowCount   int64     `db:"last_row_count" json:"last_row_count"`
	QueryVersion   int16     `db:"query_version" json:"query_version"`
}

// Recompute and upsert the rankings summary for a single
// (instance, difficulty, max_players, tenant) combo.
// The caller sets tenant context so RLS on encounter_dps_rankings
// scopes to the correct realms automatically.
// Step 1: aggregate per player per run (sum encounters within one instance run).
// Step 2: pick each player's best run.
func (q *sqlQuerier) UpsertRankingsInstanceSummary(ctx context.Context, arg UpsertRankingsInstanceSummaryParams) error {
	_, err := q.db.Exec(ctx, upsertRankingsInstanceSummary,
		arg.InstanceName,
		arg.DifficultyName,
		arg.MaxPlayers,
		arg.TenantID,
		arg.LastRowCount,
		arg.QueryVersion,
	)
	return err
}

const upsertTalentBuild = `-- name: UpsertTalentBuild :one
WITH ins AS (
    INSERT INTO talent_builds (dataset_id, player_class, talent_summary, talent_layout, spec, sub_spec)
    VALUES ($1, $2, $3, $4, $5, $6)
    ON CONFLICT (dataset_id, player_class, talent_layout) DO UPDATE SET
        spec = EXCLUDED.spec,
        sub_spec = EXCLUDED.sub_spec
    RETURNING id
)
SELECT id FROM ins
UNION ALL
SELECT id FROM talent_builds
WHERE dataset_id = $1 AND player_class = $2 AND talent_layout = $4
LIMIT 1
`

type UpsertTalentBuildParams struct {
	DatasetID     uuid.UUID   `db:"dataset_id" json:"dataset_id"`
	PlayerClass   string      `db:"player_class" json:"player_class"`
	TalentSummary []int16     `db:"talent_summary" json:"talent_summary"`
	TalentLayout  string      `db:"talent_layout" json:"talent_layout"`
	Spec          string      `db:"spec" json:"spec"`
	SubSpec       pgtype.Text `db:"sub_spec" json:"sub_spec"`
}

// Insert a unique talent build, returning its ID. If the build already exists,
// return the existing row's ID.
func (q *sqlQuerier) UpsertTalentBuild(ctx context.Context, arg UpsertTalentBuildParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertTalentBuild,
		arg.DatasetID,
		arg.PlayerClass,
		arg.TalentSummary,
		arg.TalentLayout,
		arg.Spec,
		arg.SubSpec,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const adminListOutdatedParserVersionInstances = `-- name: AdminListOutdatedParserVersionInstances :many
SELECT
  li.id,
  li.log_group_id,
  li.name,
  li.parser_version,
  li.hashed_slug,
  wsr.name as realm_name,
  u.username as uploader_name,
  wlg.created_at as uploaded_at,
  li.start_time,
  li.end_time
FROM log_instances li
JOIN parsed_log_group plg ON plg.id = li.log_group_id
JOIN wow_log_groups wlg ON wlg.id = plg.id
  AND plg.parse_generation = wlg.parse_generation
  AND plg.finalized_at IS NOT NULL
JOIN users u ON u.id = wlg.owner
JOIN wow_server_realms wsr ON wsr.id = li.realm_id
WHERE (
    -- Keep these multipliers in sync with internal/semverenc.
    COALESCE(NULLIF(regexp_replace(split_part(trim(leading 'v' from split_part(li.parser_version, '+', 1)), '.', 1), '[^0-9].*$', ''), ''), '0')::bigint * 1000000000
    + COALESCE(NULLIF(regexp_replace(split_part(trim(leading 'v' from split_part(li.parser_version, '+', 1)), '.', 2), '[^0-9].*$', ''), ''), '0')::bigint * 10000000
    + COALESCE(NULLIF(regexp_replace(split_part(trim(leading 'v' from split_part(li.parser_version, '+', 1)), '.', 3), '[^0-9].*$', ''), ''), '0')::bigint * 10000
  ) < $1::bigint
  AND ($2::text IS NULL OR li.name ILIKE '%' || $2::text || '%')
  AND EXISTS(
    SELECT 1 FROM log_file lf
    WHERE lf.wow_log_id = li.log_group_id
    AND lf.storage_deleted_at IS NULL
  )
ORDER BY (li.end_time - li.start_time) ASC NULLS LAST
LIMIT 50
`

type AdminListOutdatedParserVersionInstancesParams struct {
	MinParserVersionNum int64       `db:"min_parser_version_num" json:"min_parser_version_num"`
	InstanceName        pgtype.Text `db:"instance_name" json:"instance_name"`
}

type AdminListOutdatedParserVersionInstancesRow struct {
	ID            uuid.UUID          `db:"id" json:"id"`
	LogGroupID    uuid.UUID          `db:"log_group_id" json:"log_group_id"`
	Name          string             `db:"name" json:"name"`
	ParserVersion string             `db:"parser_version" json:"parser_version"`
	HashedSlug    pgtype.Text        `db:"hashed_slug" json:"hashed_slug"`
	RealmName     string             `db:"realm_name" json:"realm_name"`
	UploaderName  string             `db:"uploader_name" json:"uploader_name"`
	UploadedAt    pgtype.Timestamptz `db:"uploaded_at" json:"uploaded_at"`
	StartTime     pgtype.Timestamptz `db:"start_time" json:"start_time"`
	EndTime       pgtype.Timestamptz `db:"end_time" json:"end_time"`
}

func (q *sqlQuerier) AdminListOutdatedParserVersionInstances(ctx context.Context, arg AdminListOutdatedParserVersionInstancesParams) ([]AdminListOutdatedParserVersionInstancesRow, error) {
	rows, err := q.db.Query(ctx, adminListOutdatedParserVersionInstances, arg.MinParserVersionNum, arg.InstanceName)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AdminListOutdatedParserVersionInstancesRow
	for rows.Next() {
		var i AdminListOutdatedParserVersionInstancesRow
		if err := rows.Scan(
			&i.ID,
			&i.LogGroupID,
			&i.Name,
			&i.ParserVersion,
			&i.HashedSlug,
			&i.RealmName,
			&i.UploaderName,
			&i.UploadedAt,
			&i.StartTime,
			&i.EndTime,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

